    const val LON_MIN = 7.25f
    const val LON_MAX = 11.80f
    const val LAT_MIN = 30.05f
    const val LAT_MAX = 37.55f

    /** Equirectangular projection corrected at Tunisia's mid-latitude so the shape isn't stretched. */
    private val LON_SCALE = cos(Math.toRadians(33.8)).toFloat()

    /** Width / height of the map window once projected. */
    val ASPECT: Float = ((LON_MAX - LON_MIN) * LON_SCALE) / (LAT_MAX - LAT_MIN)

    /** Normalised [0..1] position of a lon/lat inside the map window. */
    fun project(lon: Float, lat: Float): Pair<Float, Float> =
        ((lon - LON_MIN) / (LON_MAX - LON_MIN)) to ((LAT_MAX - lat) / (LAT_MAX - LAT_MIN))
